    67  void RawImageData::createData() {
    68    static constexpr const auto alignment = 16;
    69
    70    if (dim.x > 65535 || dim.y > 65535)
    71      ThrowRDE("Dimensions too large for allocation.");
    72    if (dim.x <= 0 || dim.y <= 0)
    73      ThrowRDE("Dimension of one sides is less than 1 - cannot allocate image.");
    74    if (data)
    75      ThrowRDE("Duplicate data allocation in createData.");
    76
    77    // want each line to start at 16-byte aligned address
    78    pitch = roundUp(static_cast<size_t>(dim.x) * bpp, alignment);
    79    assert(isAligned(pitch, alignment));
    80
    81  #if defined(DEBUG) || __has_feature(address_sanitizer) ||                      \
    82      defined(__SANITIZE_ADDRESS__)
    83    // want to ensure that we have some padding
    84    pitch += alignment * alignment;
    85    assert(isAligned(pitch, alignment));
    86  #endif
    87
    88    padding = pitch - dim.x * bpp;
    89
    90  #if defined(DEBUG) || __has_feature(address_sanitizer) ||                      \
    91      defined(__SANITIZE_ADDRESS__)
    92    assert(padding > 0);
    93  #endif
    94
    95    data = alignedMallocArray<uchar8, alignment>(dim.y, pitch);
    96
    97    if (!data)
    98      ThrowRDE("Memory Allocation failed.");
    99
   100    uncropped_dim = dim;
   101
   102  #ifndef NDEBUG
   103    if (dim.y > 1) {
   104      // padding is the size of the area after last pixel of line n
   105      // and before the first pixel of line n+1
   106      assert(getData(dim.x - 1, 0) + bpp + padding == getData(0, 1));
   107    }
   108
   109    for (int j = 0; j < dim.y; j++) {
   110      const uchar8* const line = getData(0, j);
   111      // each line is indeed 16-byte aligned
   112      assert(isAligned(line, alignment));
   113    }
   114  #endif
   115
   116    poisonPadding();
   117  }
