   119  #if __has_feature(address_sanitizer) || defined(__SANITIZE_ADDRESS__)
   120  void RawImageData::poisonPadding() {
   121    if (padding <= 0)
   122      return;
   123
   124    for (int j = 0; j < uncropped_dim.y; j++) {
   125      const uchar8* const curr_line_end =
   126          getDataUncropped(uncropped_dim.x - 1, j) + bpp;
   127
   128      // and now poison the padding.
   129      ASAN_POISON_MEMORY_REGION(curr_line_end, padding);
   130    }
    80    ImageMetaData();
    81
    82    // Aspect ratio of the pixels, usually 1 but some cameras need scaling
    83    // <1 means the image needs to be stretched vertically, (0.5 means 2x)
    84    // >1 means the image needs to be stretched horizontally (2 mean 2x)
    85    double pixelAspectRatio;
    86
    87    // White balance coefficients of the image
    88    float wbCoeffs[4];
    89
    90    // How many pixels far down the left edge and far up the right edge the image
    91    // corners are when the image is rotated 45 degrees in Fuji rotated sensors.
    92    uint32 fujiRotationPos;
    93
    94    iPoint2D subsampling;
    95    std::string make;
    96    std::string model;
    97    std::string mode;
    98
    99    std::string canonical_make;
   100    std::string canonical_model;
   101    std::string canonical_alias;
   102    std::string canonical_id;
   103
   104    // ISO speed. If known the value is set, otherwise it will be '0'.
   105    int isoSpeed;
   106  };
